def minimal_poly(expr, x='x'):
    import sympy as sp
    X = sp.Symbol(x)
    loc = {x: X, 'x': X, 'sqrt': sp.sqrt, 'Rational': sp.Rational, 'pi': sp.pi, 'E': sp.E, 'I': sp.I}
    e = sp.sympify(expr, locals=loc)
    p = sp.minimal_polynomial(e, X)
    p = sp.Poly(p, X).monic()
    return str(sp.expand(p.as_expr()))
